package com.globaltrade.common.dto;

import java.io.Serializable;
import java.time.LocalDateTime;

/**
 * DTO for inventory alert notifications.
 * Generated by the InventoryMonitorTimer when stock levels fall
 * below reorder thresholds.
 */
public class InventoryAlertDTO implements Serializable {

    private static final long serialVersionUID = 1L;

    private Long itemId;
    private String sku;
    private String productName;
    private Long warehouseId;
    private String warehouseName;
    private int currentQuantity;
    private int reorderLevel;
    private String alertType; // LOW_STOCK, OUT_OF_STOCK, OVERSTOCK
    private String severity;  // CRITICAL, WARNING, INFO
    private LocalDateTime alertTimestamp;
    private String suggestedAction;

    public InventoryAlertDTO() {
    }

    // ======================== Getters and Setters ========================

    public Long getItemId() {
        return itemId;
    }

    public void setItemId(Long itemId) {
        this.itemId = itemId;
    }

    public String getSku() {
        return sku;
    }

    public void setSku(String sku) {
        this.sku = sku;
    }

    public String getProductName() {
        return productName;
    }

    public void setProductName(String productName) {
        this.productName = productName;
    }

    public Long getWarehouseId() {
        return warehouseId;
    }

    public void setWarehouseId(Long warehouseId) {
        this.warehouseId = warehouseId;
    }

    public String getWarehouseName() {
        return warehouseName;
    }

    public void setWarehouseName(String warehouseName) {
        this.warehouseName = warehouseName;
    }

    public int getCurrentQuantity() {
        return currentQuantity;
    }

    public void setCurrentQuantity(int currentQuantity) {
        this.currentQuantity = currentQuantity;
    }

    public int getReorderLevel() {
        return reorderLevel;
    }

    public void setReorderLevel(int reorderLevel) {
        this.reorderLevel = reorderLevel;
    }

    public String getAlertType() {
        return alertType;
    }

    public void setAlertType(String alertType) {
        this.alertType = alertType;
    }

    public String getSeverity() {
        return severity;
    }

    public void setSeverity(String severity) {
        this.severity = severity;
    }

    public LocalDateTime getAlertTimestamp() {
        return alertTimestamp;
    }

    public void setAlertTimestamp(LocalDateTime alertTimestamp) {
        this.alertTimestamp = alertTimestamp;
    }

    public String getSuggestedAction() {
        return suggestedAction;
    }

    public void setSuggestedAction(String suggestedAction) {
        this.suggestedAction = suggestedAction;
    }
}
